import { describe, expect, test } from 'vitest';
import { generateShelterSpec, generateTreeSpec } from '../features/fabrication/spec';
import { buildGraph } from '../lib/graph';
import { createEvaluator } from '../lib/optimizer';
import { AREA_INDEX, DEFAULT_AREA_ID } from './areas';
import { areaContextSchema, loadContext } from './context';
import { loadDataset } from './load';

/** Checks on every shipped real-area dataset (generated by `npm run data:areas`). */
const MALAY_WORDS = /\b(jalan|lorong|persiaran|lebuh|sekolah|masjid|surau|perumahan|rumah)\b/i;
const TIME_SLOTS = ['09:00', '12:00', '14:00', '17:00'] as const;

const loaded = await Promise.all(
  AREA_INDEX.map(async (entry) => ({
    entry,
    data: await loadDataset(entry.slug),
    context: await loadContext(entry.slug),
  })),
);

describe('area index', () => {
  test('lists the default area and several more across the valley', () => {
    expect(AREA_INDEX.some((a) => a.slug === DEFAULT_AREA_ID)).toBe(true);
    expect(AREA_INDEX.length).toBeGreaterThanOrEqual(6);
    expect(new Set(AREA_INDEX.map((a) => a.slug)).size).toBe(AREA_INDEX.length);
    expect(new Set(AREA_INDEX.map((a) => a.group)).size).toBeGreaterThanOrEqual(2);
  });
});

describe.each(loaded)('area $entry.slug', ({ entry, data, context }) => {
  const { neighbourhood, journeys, interventions, unitCosts } = data;
  const meta = neighbourhood.meta!;
  const graph = buildGraph(neighbourhood.nodes, neighbourhood.segments);

  test('has metadata, a demo journey and a sensible budget', () => {
    expect(meta.name).toBe(entry.name);
    expect(meta.source).toBe('openstreetmap');
    expect(meta.attribution).toMatch(/OpenStreetMap/);
    expect(meta.assumptions!.length).toBeGreaterThan(2);
    expect(meta.budget.demo).toBeLessThanOrEqual(meta.budget.max);
    expect(journeys.some((j) => j.id === meta.demoJourneyId)).toBe(true);
  });

  test('has enough paths, homes and journeys', () => {
    expect(neighbourhood.segments.length).toBeGreaterThanOrEqual(40);
    expect(neighbourhood.destinations.filter((d) => d.kind === 'home').length).toBeGreaterThanOrEqual(1);
    expect(journeys.length).toBeGreaterThanOrEqual(4);
  });

  test('uses plain English for everything people read', () => {
    const texts = [
      ...neighbourhood.destinations.map((d) => d.name),
      ...neighbourhood.segments.map((s) => s.notes ?? ''),
      ...interventions.map((i) => i.name),
      ...(meta.assumptions ?? []),
    ];
    texts.forEach((text) => expect(text, text).not.toMatch(MALAY_WORDS));
  });

  test('every candidate costs what its bill of materials says (rounded)', () => {
    for (const i of interventions) {
      const length = i.segmentIds.reduce((sum, id) => sum + (graph.lengthBySegment.get(id) ?? 0), 0);
      const spec =
        i.type === 'shelter'
          ? generateShelterSpec(i, neighbourhood.segments, unitCosts, graph.lengthBySegment)
          : generateTreeSpec(i, unitCosts, length);
      const tolerance = i.type === 'shelter' ? 500 : 50;
      expect(Math.abs(i.installCost - spec.totalCost), i.name).toBeLessThanOrEqual(tolerance);
    }
  });

  test('the demo budget recommends an affordable plan that reduces direct sun', () => {
    const evaluator = createEvaluator({
      graph,
      segments: neighbourhood.segments,
      destinations: neighbourhood.destinations,
      journeys,
      candidates: interventions,
      time: '14:00',
      canopy: 'now',
      canopyYear: 0,
      detourLimit: 0.25,
      priorityWeights: {},
      overrides: [],
    });
    const [best] = evaluator.recommend(meta.budget.demo);
    expect(best).toBeDefined();
    expect(best!.installCost).toBeLessThanOrEqual(meta.budget.demo);
    expect(best!.sunMinutesAvoidedPerDay).toBeGreaterThan(0);
  });

  test('shade values are valid, estimated, and no lower in the morning than at 2 pm', () => {
    neighbourhood.segments.forEach((s) => {
      expect(s.shadeSource).toBe('estimated');
      TIME_SLOTS.forEach((t) => {
        expect(s.shade[t]).toBeGreaterThanOrEqual(0);
        expect(s.shade[t]).toBeLessThanOrEqual(1);
      });
    });
    const mean = (t: (typeof TIME_SLOTS)[number]) =>
      neighbourhood.segments.reduce((sum, x) => sum + x.shade[t], 0) / neighbourhood.segments.length;
    expect(mean('09:00')).toBeGreaterThanOrEqual(mean('14:00') - 0.001);
  });

  test('area context is valid and has buildings and named places in English', () => {
    expect(context).not.toBeNull();
    expect(() => areaContextSchema.parse(context)).not.toThrow();
    expect(context!.buildings.length).toBeGreaterThan(50);
    context!.landmarks.forEach((l) => expect(l.name, l.name).not.toMatch(MALAY_WORDS));
  });
});
